import{_ as a,C as r,o as s,c as l,a6 as g,E as e,j as o,a as i}from"./chunks/framework.CrjICMdL.js";const c="/rb_cobot_docs_muscat/images/program/force-form.avif",f=JSON.parse('{"title":"힘 제어","description":"","frontmatter":{"title":"힘 제어","outline":[2,3]},"headers":[],"relativePath":"manual/program/force-control.md","filePath":"manual/program/force-control.md","lastUpdated":1792487136000}'),h={name:"manual/program/force-control.md"};function p(m,t,b,x,u,_){const n=r("DemoFrame"),d=r("ScenarioSteps");return s(),l("div",null,[t[0]||(t[0]=g('<h1 id="힘-제어" tabindex="-1">힘 제어 <a class="header-anchor" href="#힘-제어" aria-label="Permalink to &quot;힘 제어&quot;">​</a></h1><p><strong>힘 제어</strong>는 로봇이 정한 <strong>축 방향으로 정한 힘</strong>을 유지하도록 제어하는 명령입니다. 로봇이 물체에 닿았을 때 밀어붙이는 힘을 일정하게 유지하거나, 접촉하는 방향으로만 힘에 따라 움직이게 하고 싶을 때 사용합니다. 코어는 이 기능을 <strong>어드미턴스 힘 제어</strong>로 실행합니다.</p><p>이 문서에서는 <strong>프로그램</strong> 화면에서 다음을 해 봅니다.</p><ul><li>힘 제어를 추가하고 모드 고르기</li><li>힘 제어를 켜고 축별 목표 값 정하기</li><li>센서·제한 설정 확인하기</li></ul><div class="warning custom-block"><p class="custom-block-title">안전</p><p>힘 제어는 프로그램을 <strong>실행하면 로봇이 실제로 힘을 내며 움직이는</strong> 명령입니다. 목표 값·게인·속도 제한·최대 편차를 확인하고 로봇 주변을 정리한 뒤 사용합니다. 아래의 실습은 로봇이 움직이지 않는 화면입니다.</p></div><h2 id="모드" tabindex="-1">모드 <a class="header-anchor" href="#모드" aria-label="Permalink to &quot;모드&quot;">​</a></h2><p>힘 제어는 <strong>모드</strong>로 하는 일을 고릅니다. 처음 추가하면 <strong>끄기</strong>입니다.</p><table tabindex="0"><thead><tr><th>모드</th><th>하는 일</th></tr></thead><tbody><tr><td><strong>끄기</strong></td><td>힘 제어를 멈춥니다. 정할 값이 없습니다.</td></tr><tr><td><strong>켜기</strong></td><td>힘 제어를 시작합니다. 목표 설정·제한 설정·센서 설정·기타를 모두 정합니다.</td></tr><tr><td><strong>힘 설정값 변경</strong></td><td>이미 켜져 있는 힘 제어의 목표 설정과 제한 설정을 바꿉니다. 센서 설정과 접촉 감지 힘은 켜져 있는 동안 바꿀 수 없어 이 모드에는 없습니다.</td></tr></tbody></table><h2 id="켜기-모드의-설정-화면" tabindex="-1">켜기 모드의 설정 화면 <a class="header-anchor" href="#켜기-모드의-설정-화면" aria-label="Permalink to &quot;켜기 모드의 설정 화면&quot;">​</a></h2><p>모드를 <strong>켜기</strong>로 고른 화면입니다. 아래는 모든 값이 기본값인 상태입니다.</p><p><img src="'+c+'" alt="힘 제어 켜기 모드 설정 화면"></p><h3 id="모드·목표-설정-1-7" tabindex="-1">모드·목표 설정 (①~⑦) <a class="header-anchor" href="#모드·목표-설정-1-7" aria-label="Permalink to &quot;모드·목표 설정 (①~⑦)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">①</td><td><strong>모드</strong></td><td>끄기·켜기·힘 설정값 변경 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">②</td><td><strong>목표 좌표계</strong></td><td>힘의 방향을 정하는 기준입니다. 전역 좌표계, 로컬 좌표계, 사용자 좌표계, 목표 좌표계 중에서 고릅니다.</td></tr><tr><td style="text-align:center;">③</td><td><strong>활성화</strong></td><td>축(X·Y·Z·Rx·Ry·Rz)마다 체크합니다. <strong>체크한 축만</strong> 힘 제어를 적용합니다.</td></tr><tr><td style="text-align:center;">④</td><td><strong>목표값</strong></td><td>축 방향으로 유지할 힘(X·Y·Z)이나 토크(Rx·Ry·Rz)입니다. 기본값은 0입니다.</td></tr><tr><td style="text-align:center;">⑤</td><td><strong>P-Gain</strong></td><td>축별 P 게인입니다. 기본값은 0입니다.</td></tr><tr><td style="text-align:center;">⑥</td><td><strong>I-Gain</strong></td><td>축별 I 게인입니다. 기본값은 0입니다.</td></tr><tr><td style="text-align:center;">⑦</td><td><strong>속도 제한</strong></td><td>축별 속도 제한입니다. 기본값은 0입니다.</td></tr></tbody></table></div><h3 id="제한·센서·기타-8-13" tabindex="-1">제한·센서·기타 (⑧~⑬) <a class="header-anchor" href="#제한·센서·기타-8-13" aria-label="Permalink to &quot;제한·센서·기타 (⑧~⑬)&quot;">​</a></h3><div class="tbl-nowrap-2"><table tabindex="0"><thead><tr><th style="text-align:center;">번호</th><th>항목</th><th>설명</th></tr></thead><tbody><tr><td style="text-align:center;">⑧</td><td><strong>위치 최대 편차 (mm)</strong></td><td>위치의 최대 편차를 mm 단위로 정합니다.</td></tr><tr><td style="text-align:center;">⑨</td><td><strong>회전 최대 편차 (deg)</strong></td><td>회전의 최대 편차를 deg 단위로 정합니다.</td></tr><tr><td style="text-align:center;">⑩</td><td><strong>센서 타입</strong></td><td>힘을 읽을 센서입니다. External F/T, Internal F/T, Analog Input 0~3, Custom 중에서 고릅니다. 기본값은 External F/T입니다.</td></tr><tr><td style="text-align:center;">⑪</td><td><strong>센서 필터 (Hz)</strong></td><td>센서 값에 적용하는 필터(저역 통과)의 주파수입니다. 기본값은 20입니다.</td></tr><tr><td style="text-align:center;">⑫</td><td><strong>센서 신호 옵션</strong></td><td><strong>자동 영점 조정</strong>과 <strong>원시값</strong> 중에서 고릅니다. 기본값은 자동 영점 조정입니다.</td></tr><tr><td style="text-align:center;">⑬</td><td><strong>접촉 감지 힘 (N)</strong></td><td>접촉했다고 판단하는 힘입니다. 기본값은 5입니다.</td></tr><tr><td style="text-align:center;">⑭</td><td><strong>닫기</strong></td><td>설정 화면을 닫습니다. 저장하지 않은 변경이 있으면 저장하지 않고 닫을지 묻습니다.</td></tr><tr><td style="text-align:center;">⑮</td><td><strong>저장</strong></td><td>설정을 적용하고 설정 화면을 닫습니다. 트리의 힘 제어 옆에 목표 좌표계와 모드가 표시됩니다.</td></tr></tbody></table></div><p>센서 설정(⑩~⑫)과 기타(⑬)는 <strong>켜기 모드에만</strong> 나타납니다. 힘 설정값 변경 모드에는 ①~⑨와 같은 목표 설정·제한 설정만 있습니다.</p><h2 id="직접-해-보기" tabindex="-1">직접 해 보기 <a class="header-anchor" href="#직접-해-보기" aria-label="Permalink to &quot;직접 해 보기&quot;">​</a></h2><p>힘 제어를 추가해 켜기 모드로 바꾸고, Z축을 활성화해 목표값을 정해 봅니다. 실습의 로봇은 실제로 움직이지 않으며 프로그램을 실행하지 않습니다. 다음 순서로 진행합니다.</p><ol><li>트리의 빈 영역을 눌러 위치를 정하고 편집 아이콘으로 명령어 목록을 연 뒤 <strong>힘 제어</strong>를 추가합니다. 처음 모드는 끄기입니다.</li><li>트리에서 힘 제어를 눌러 설정 화면을 열고 모드를 <strong>켜기</strong>로 바꿉니다.</li><li>목표 설정에서 <strong>Z 줄의 활성화</strong>를 체크합니다.</li><li>Z 줄의 목표값에 <code>10</code>을 입력합니다. 입력한 값이 안내와 같아야 다음으로 넘어갈 수 있으며, 건너뛰면 자동으로 입력됩니다.</li><li>제한 설정·센서 설정·기타는 기본값 그대로 두고 <strong>저장</strong>을 누르면 트리의 힘 제어 옆에 기준 좌표계와 모드가 표시됩니다.</li></ol>',19)),e(n,{id:"program-force-control"}),t[1]||(t[1]=o("h2",{id:"사용-방법",tabindex:"-1"},[i("사용 방법 "),o("a",{class:"header-anchor",href:"#사용-방법","aria-label":'Permalink to "사용 방법"'},"​")],-1)),e(d,{id:"program-force-control"})])}const P=a(h,[["render",p]]);export{f as __pageData,P as default};
